  console.log("\n[4] Plugin Load & Tool Registration")
  try {
    const mod = await import(pluginDist + "?t=" + Date.now())
    if (typeof mod.AgenticEngine === "function") {
      ok("AgenticEngine exported as function")
    } else {
      fail("AgenticEngine not exported")
      process.exit(1)
    }

